def _features(z, g, kind, form):
    b = _saturate(z, g, kind)
    cross = (z[:, :, None] * b[:, None, :]).reshape(len(z), -1)
    a = np.c_[poly(z, 2), b, cross]
    if form == 1:
        a = np.c_[a, poly(b, 2)[:, 5:]]
    elif form == 2:
        a = np.c_[a, b * b]
    elif form == 3:
        a = np.c_[a, z ** 3]
    elif form == 4:
